123	function takeText(value: string, context: SanitizationContext): string {
124	  const redacted = redactSensitiveText(value, context.secretValues);
125	  const available = Math.min(MAX_TRACE_STRING_LENGTH, context.remainingText);
126	  if (available <= 0) return TRUNCATED;
127	  context.remainingText -= Math.min(redacted.length, available);
128	  return redacted.length > available ? `${redacted.slice(0, available)}${TRUNCATED}` : redacted;
129	}
