131	function sanitizeValue(value: unknown, context: SanitizationContext, depth: number): TraceValue {
132	  if (depth > MAX_TRACE_DEPTH) return TRUNCATED;
133	  if (value === undefined) return '[UNDEFINED]';
134	  if (value === null || typeof value === 'boolean') return value;
135	  if (typeof value === 'number') return Number.isFinite(value) ? value : String(value);
136	  if (typeof value === 'string') return takeText(value, context);
137	  if (typeof value === 'bigint' || typeof value === 'symbol' || typeof value === 'function') {
138	    return takeText(String(value), context);
139	  }
140	
141	  if (context.seen.has(value)) return '[CIRCULAR]';
142	  context.seen.add(value);
143	
144	  if (Array.isArray(value)) {
145	    const items = value.slice(0, MAX_TRACE_ARRAY_ITEMS)
146	      .map((item) => sanitizeValue(item, context, depth + 1));
147	    if (value.length > MAX_TRACE_ARRAY_ITEMS) items.push(TRUNCATED);
148	    return items;
149	  }
150	
151	  if (!isRecord(value)) return takeText(String(value), context);
152	
153	  const entries: { [key: string]: TraceValue } = {};
154	  const objectEntries = Object.entries(value).slice(0, MAX_TRACE_OBJECT_ENTRIES);
155	  for (const [key, entry] of objectEntries) {
156	    entries[redactSensitiveText(key, context.secretValues)] = SENSITIVE_KEY.test(key)
157	      ? REDACTED
158	      : sanitizeValue(entry, context, depth + 1);
159	  }
160	  if (Object.keys(value).length > MAX_TRACE_OBJECT_ENTRIES) entries.truncated = TRUNCATED;
161	  return entries;
162	}
