216	async function uniqueTracePath(root: string): Promise<{ path: string; runId: string }> {
217	  const traceDir = path.join(root, 'traces');
218	  await mkdir(traceDir, { recursive: true });
219	
220	  for (let attempt = 0; attempt < MAX_TRACE_WRITE_ATTEMPTS; attempt += 1) {
221	    const date = new Date();
222	    const runId = `${date.toISOString().replaceAll(':', '-').replaceAll('.', '-')}-${randomUUID()}`;
223	    const tracePath = path.join(traceDir, `${runId}.jsonl`);
224	    try {
225	      await writeFile(tracePath, '', { flag: 'wx' });
226	      return { path: tracePath, runId };
227	    } catch (error) {
228	      if (isFileExistsError(error)) continue;
229	      throw error;
230	    }
231	  }
232	
233	  throw new Error('Unable to allocate a unique trace path.');
234	}
