 10	export const SNAPSHOT_FILE_LIMIT = 512;
 11	export const SNAPSHOT_FILE_BYTES = 1_048_576;
 12	export const SNAPSHOT_TOTAL_BYTES = 32 * 1_048_576;
 13	export const SNAPSHOT_RECORD_BYTES = 512 * 1_024;
