 20	function safePath(file: string): boolean {
 21	  return file.length > 0 && file.length <= 512 && !path.isAbsolute(file) &&
 22	    !file.includes('\\') && !/[\u0000-\u001f\u007f\ufffd]/u.test(file) &&
 23	    !file.split('/').some((part) => part === '' || part === '.' || part === '..');
 24	}
 25	
 26	function excluded(file: string): boolean {
 27	  return file.split('/').some((part) =>
 28	    /^(?:\.git|\.env(?:\..*)?|\.npmrc|\.netrc|\.ssh|\.aws|credentials?.*|secrets?.*|id_(?:rsa|dsa|ecdsa|ed25519).*|node_modules|dist|traces|\.entire|\.cache|\.next|\.turbo|coverage|\.venv)$/iu.test(part)) ||
 29	    /\.(?:key|pem|p12|pfx)$/iu.test(file);
 30	}
 31	
 32	export function isRepositorySnapshot(value: unknown): value is RepositorySnapshot {
 33	  if (value === null || typeof value !== 'object' || !('version' in value) || value.version !== 1 ||
 34	      !('files' in value) || !Array.isArray(value.files) || value.files.length > SNAPSHOT_FILE_LIMIT ||
 35	      Object.keys(value).length !== 2) return false;
 36	  const names = new Set<string>();
 37	  return value.files.every((item: unknown) => {
 38	    if (item === null || typeof item !== 'object' || Object.keys(item).length !== 2 ||
 39	        !('path' in item) || typeof item.path !== 'string' || !safePath(item.path) || excluded(item.path) ||
 40	        redactSensitiveText(item.path) !== item.path ||
 41	        names.has(item.path) || !('hash' in item) || (item.hash !== null &&
 42	          (typeof item.hash !== 'string' || !/^[a-f0-9]{64}$/u.test(item.hash)))) return false;
 43	    names.add(item.path);
 44	    return true;
 45	  });
 46	}
