 52	export async function captureRepositorySnapshot(repository: SavedRunRepository): Promise<RepositorySnapshot> {
 53	  const identity = await inspectGitIdentity(repository.root);
 54	  if (identity.root !== repository.root || identity.gitCommonDirectory !== repository.gitCommonDirectory || identity.head !== repository.head) {
 55	    throw new Error('Saved repository identity or HEAD changed; continuation is blocked.');
 56	  }
 57	  const enumerated = await inspectGitFiles(repository.root);
 58	  const names = [...new Set([
 59	    ...enumerated, 'package.json', ...REPOSITORY_INSTRUCTION_FILES,
 60	  ])].filter((file) => !excluded(file)).sort();
 61	  if (names.length > SNAPSHOT_FILE_LIMIT || names.some((file) => !safePath(file))) {
 62	    throw new Error('Repository file comparison exceeds its bounds or contains an unsafe path.');
 63	  }
 64	  if (names.some((file) => redactSensitiveText(file) !== file)) {
 65	    throw new Error('Repository comparison paths contain sensitive text and cannot be retained safely.');
 66	  }
 67	  let total = 0;
 68	  const observed = new Map<string, string | null>();
 69	  const metadata = (entry: { ino: number; dev: number; size: number; mtimeMs: number; ctimeMs: number }): string =>
 70	    JSON.stringify([entry.ino, entry.dev, entry.size, entry.mtimeMs, entry.ctimeMs]);
 71	  const files: RepositorySnapshot['files'] = [];
 72	  for (const name of names) {
 73	    const file = path.join(repository.root, name);
 74	    let details;
 75	    try { details = await lstat(file); } catch (error) {
 76	      if (error !== null && typeof error === 'object' && 'code' in error && error.code === 'ENOENT') {
 77	        files.push({ path: name, hash: null });
 78	        observed.set(name, null);
 79	        continue;
 80	      }
 81	      throw new Error('Repository file comparison is unavailable.');
 82	    }
 83	    if (!details.isFile() || details.isSymbolicLink() || details.nlink !== 1 ||
 84	        details.size > SNAPSHOT_FILE_BYTES || await realpath(file) !== file) {
 85	      throw new Error('Repository comparison requires bounded regular files without links.');
 86	    }
 87	    total += details.size;
 88	    if (total > SNAPSHOT_TOTAL_BYTES) throw new Error('Repository content comparison exceeds its total byte limit.');
 89	    const handle = await open(file, constants.O_RDONLY | (process.platform === 'win32' ? 0 : constants.O_NOFOLLOW ?? 0));
 90	    try {
 91	      const before = await handle.stat();
 92	      const buffer = Buffer.alloc(details.size + 1);
 93	      let offset = 0;
 94	      while (offset < buffer.length) {
 95	        const result = await handle.read(buffer, offset, buffer.length - offset, offset);
 96	        if (result.bytesRead === 0) break;
 97	        offset += result.bytesRead;
 98	      }
 99	      const after = await handle.stat();
100	      const current = await lstat(file);
101	      if (offset !== details.size || before.ino !== details.ino || before.dev !== details.dev ||
102	          before.nlink !== 1 || after.nlink !== 1 || before.mtimeMs !== details.mtimeMs ||
103	          after.size !== before.size || after.mtimeMs !== before.mtimeMs || after.ctimeMs !== before.ctimeMs ||
104	          current.ino !== before.ino || current.dev !== before.dev || current.isSymbolicLink()) {
105	        throw new Error('Repository contents changed during comparison. Retry after edits stop.');
106	      }
107	      files.push({ path: name, hash: createHash('sha256').update(buffer.subarray(0, offset)).digest('hex') });
108	      observed.set(name, metadata(after));
109	    } finally { await handle.close(); }
110	  }
111	  if (JSON.stringify(enumerated) !== JSON.stringify(await inspectGitFiles(repository.root))) {
112	    throw new Error('Repository file enumeration changed during comparison.');
113	  }
114	  for (const name of names) {
115	    let current: string | null;
116	    try { current = metadata(await lstat(path.join(repository.root, name))); } catch (error) {
117	      if (error !== null && typeof error === 'object' && 'code' in error && error.code === 'ENOENT') current = null;
118	      else throw new Error('Repository metadata could not be rechecked.');
119	    }
120	    if (current !== observed.get(name)) throw new Error('Repository contents changed during comparison.');
121	  }
122	  const finalIdentity = await inspectGitIdentity(repository.root);
123	  if (JSON.stringify(finalIdentity) !== JSON.stringify(identity)) throw new Error('Repository identity changed during comparison.');
124	  return { version: 1, files };
125	}
