127	export function changedSnapshotPaths(previous: RepositorySnapshot, current: RepositorySnapshot): string[] {
128	  const before = new Map(previous.files.map((item) => [item.path, item.hash]));
129	  const after = new Map(current.files.map((item) => [item.path, item.hash]));
130	  return [...new Set([...before.keys(), ...after.keys()])].filter((file) => before.get(file) !== after.get(file)).sort();
131	}

