825	        fail('limit_reached', 'Saved run iteration limit cannot be exceeded or reset.');
826	      }
827	      if (state.task !== previous.state.task || state.repo.root !== previous.repository.root ||
828	          state.workerSelection !== previous.configuration.workerSelection ||
829	          (state.codexNetworkAccess === true) !== previous.configuration.codexNetworkAccess ||
830	          state.codexCalls < previous.state.codexCalls || state.claudeCalls < previous.state.claudeCalls) {
