836	      const checkpoint = checkpointFrom(previous, {
837	        schemaVersion: SAVED_RUN_SCHEMA_VERSION,
838	        runId: previous.runId,
839	        createdAt: previous.createdAt,
840	        iterationLimit: previous.iterationLimit,
841	        repository: previous.repository,
842	        configuration: previous.configuration,
843	        state,
844	      }, event);
845	      validateEventSequence([...events, event], checkpoint);
846	      if (repositorySnapshot) {
847	        await atomicWrite(path.join(this.runsDirectory, runId, 'repository.json'), JSON.stringify(repositorySnapshot), SNAPSHOT_RECORD_BYTES);
848	      }
849	      await appendDurably(eventFilePath(this.directory, runId), `${JSON.stringify(event)}\n`, eventTotalLimit());
850	      await atomicWrite(checkpointFilePath(this.directory, runId), `${JSON.stringify(checkpoint)}\n`, SAVED_RUN_CHECKPOINT_LIMIT_BYTES);
