508	function checkpointFrom(
509	  previous: SavedRunCheckpointV1 | undefined,
510	  input: Omit<SavedRunCheckpointV1, 'checksum' | 'sequence' | 'ledgerHead' | 'updatedAt' | 'status'>,
511	  event: SavedRunEvent,
512	): SavedRunCheckpointV1 {
513	  const body = {
514	    schemaVersion: SAVED_RUN_SCHEMA_VERSION,
515	    runId: input.runId,
516	    createdAt: input.createdAt,
517	    updatedAt: event.timestamp,
518	    sequence: event.sequence,
519	    ledgerHead: event.hash,
520	    status: eventStatus(eventData(event)),
521	    iterationLimit: input.iterationLimit,
522	    repository: input.repository,
523	    configuration: input.configuration,
524	    state: input.state,
525	  } satisfies Omit<SavedRunCheckpointV1, 'checksum'>;
526	  if (previous && (previous.runId !== body.runId || previous.createdAt !== body.createdAt ||
527	      previous.iterationLimit !== body.iterationLimit || JSON.stringify(previous.repository) !== JSON.stringify(body.repository) ||
528	      JSON.stringify(previous.configuration) !== JSON.stringify(body.configuration) || previous.state.task !== body.state.task)) {
529	    fail('invalid_input', 'Saved run identity and approved configuration are immutable.');
530	  }
