534	async function acquireFileLock(
535	  directory: string,
536	  name: string,
537	  kind: SavedRunOwnership['kind'],
538	  key: string,
539	): Promise<SavedRunOwnership> {
540	  const file = lockPath(directory, name);
541	  const token = randomUUID();
542	  const details = JSON.stringify({ schemaVersion: SAVED_RUN_SCHEMA_VERSION, kind, key, token, pid: process.pid, createdAt: new Date().toISOString() });
543	  let handle;
544	  let created = false;
545	  try {
546	    handle = await open(file, 'wx', 0o600);
547	    created = true;
548	    await handle.writeFile(details, 'utf8');
549	    await handle.sync();
550	    await handle.close();
551	    handle = undefined;
552	    await syncDirectory(path.dirname(file));
553	  } catch (error) {
554	    if (handle) await handle.close().catch(() => undefined);
555	    if (created) await rm(file, { force: true }).catch(() => undefined);
556	    if (hasErrorCode(error, 'EEXIST')) fail('busy', 'Another process owns this saved run or worktree.');
557	    if (error instanceof SavedRunStoreError) throw error;
558	    throw new SavedRunStoreError('storage_failure', 'Unable to acquire saved run ownership.');
559	  }
560	  let released = false;
561	  return {
562	    kind,
563	    key,
564	    token,
565	    lockPath: file,
566	    async release(): Promise<void> {
567	      if (released) return;
568	      released = true;
569	      let raw: string;
570	      try { raw = await boundedRead(file, MAX_LOCK_BYTES); } catch {
571	        fail('busy', 'Saved run ownership changed before it could be released.');
572	      }
573	      let lock: unknown;
574	      try { lock = parseSavedRunJson(raw); } catch { fail('busy', 'Saved run ownership changed before it could be released.'); }
575	      if (!isRecord(lock) || lock.token !== token || lock.key !== key || lock.kind !== kind) {
576	        fail('busy', 'Saved run ownership changed before it could be released.');
577	      }
578	      try {
579	        await unlink(file);
580	        await syncDirectory(path.dirname(file));
581	      } catch {
582	        fail('storage_failure', 'Unable to release saved run ownership.');
583	      }
584	    },
585	  };
586	}
