588	export class SavedRunStore {
589	  readonly directory: string;
590	  readonly runsDirectory: string;
591	  readonly locksDirectory: string;
592	
593	  private constructor(directory: string) {
594	    this.directory = directory;
595	    this.runsDirectory = path.join(directory, 'runs');
596	    this.locksDirectory = path.join(directory, 'locks');
597	  }
