599	  static async open(directory: string = defaultSavedRunDirectory()): Promise<SavedRunStore> {
600	    try {

601	      const root = await ensurePrivateDirectory(directory);
602	      const runs = await ensurePrivateDirectory(path.join(root, 'runs'));
603	      const locks = await ensurePrivateDirectory(path.join(root, 'locks'));
604	      if (runs !== path.join(root, 'runs') || locks !== path.join(root, 'locks')) {
605	        fail('storage_failure', 'Saved run storage contains a symbolic link.');
606	      }
607	      return new SavedRunStore(root);
608	    } catch (error) {
609	      if (error instanceof SavedRunStoreError) throw error;
610	      throw new SavedRunStoreError('storage_failure', 'Unable to open saved run storage.');
611	    }
612	  }
