614	  /** Inspection never initializes storage, changes permissions, or acquires ownership. */
615	  static async openForInspection(directory: string = defaultSavedRunDirectory()): Promise<SavedRunStore | undefined> {
616	    try {
617	      let root;
618	      try { root = await lstat(directory); } catch (error) {
619	        if (hasErrorCode(error, 'ENOENT')) return undefined;
620	        throw error;
621	      }
622	      if (!root.isDirectory() || root.isSymbolicLink()) {
623	        fail('storage_failure', 'Saved run storage is not a regular directory.');
624	      }
625	      const canonical = await realpath(directory);
626	      for (const name of ['runs', 'locks']) {
627	        const child = path.join(canonical, name);
628	        const details = await lstat(child);
629	        if (!details.isDirectory() || details.isSymbolicLink() || await realpath(child) !== child) {
630	          fail('storage_failure', 'Saved run storage contains an invalid directory.');
631	        }
632	      }
633	      return new SavedRunStore(canonical);
634	    } catch (error) {
635	      if (error instanceof SavedRunStoreError) throw error;
636	      throw new SavedRunStoreError('storage_failure', 'Unable to inspect saved run storage.');
637	    }
638	  }
639	
640	  async listIdsForInspection(): Promise<{ runIds: string[]; ignoredEntries: number }> {
641	    const runIds: string[] = [];
642	    let scanned = 0;
643	    let ignoredEntries = 0;
644	    try {
645	      const directory = await opendir(this.runsDirectory);
646	      for await (const entry of directory) {
647	        scanned += 1;
648	        if (scanned > SAVED_RUN_COUNT_LIMIT) fail('limit_reached', 'Saved run store exceeds its entry limit. Inspect a known run ID directly.');
649	        if (isSavedRunId(entry.name)) runIds.push(entry.name);
650	        else ignoredEntries += 1;
651	      }
652	      return { runIds: runIds.sort(), ignoredEntries };
653	    } catch (error) {
654	      if (error instanceof SavedRunStoreError) throw error;
655	      throw new SavedRunStoreError('storage_failure', 'Unable to list saved run storage.');
656	    }
657	  }
