659	  async readForInspection(runId: string): Promise<{
660	    checkpoint: SavedRunCheckpointV1;
661	    events: SavedRunEvent[];
662	    ownership: { run: boolean; worktree: boolean };
663	  }> {
664	    if (!isSavedRunId(runId)) fail('invalid_input', 'Saved run ID is invalid.');
665	    const exists = async (name: string): Promise<boolean> => {
666	      try { await lstat(lockPath(this.directory, name)); return true; } catch (error) {
667	        if (hasErrorCode(error, 'ENOENT')) return false;
668	        fail('storage_failure', 'Saved run ownership could not be inspected.');
669	      }
670	    };
671	    const requireStableRead = async (): Promise<void> => {
672	      if (await exists(`update-${runId}`)) {
673	        fail('busy', 'Saved run is being updated or has unresolved update ownership.');
674	      }
675	    };
676	    await requireStableRead();
677	    // A concurrent write may yield an integrity error. Never repair or guess at
678	    // partially committed evidence, and never use this snapshot to authorize work.
679	    const record = await this.readUnlocked(runId);
680	    await requireStableRead();
681	    const root = record.checkpoint.repository.root;
682	    const key = sha256(process.platform === 'win32' ? root.toLowerCase() : root);
683	    return {
684	      ...record,
685	      ownership: {
686	        run: await exists(`run-${runId}`),
687	        worktree: await exists(`worktree-${key}`),
688	      },
689	    };
690	  }
