692	  async acquireRunOwnership(runId: string): Promise<SavedRunOwnership> {
693	    if (!isSavedRunId(runId)) fail('invalid_input', 'Saved run ID is invalid.');
694	    return acquireFileLock(this.directory, `run-${runId}`, 'run', runId);
695	  }
696	
697	  async acquireWorktreeOwnership(root: string): Promise<SavedRunOwnership> {
698	    let canonicalRoot: string;
699	    try { canonicalRoot = await realpath(root); } catch { fail('invalid_input', 'Worktree path is unavailable.'); }
700	    if (!path.isAbsolute(canonicalRoot)) fail('invalid_input', 'Worktree path is invalid.');
701	    const relative = path.relative(canonicalRoot, this.directory);
702	    if (relative === '' || (!relative.startsWith(`..${path.sep}`) && relative !== '..' && !path.isAbsolute(relative))) {
703	      fail('invalid_input', 'Saved run storage must be outside the selected worktree.');
704	    }
705	    const key = sha256(process.platform === 'win32' ? canonicalRoot.toLowerCase() : canonicalRoot);
706	    return acquireFileLock(this.directory, `worktree-${key}`, 'worktree', key);
707	  }
