709	  async create(input: SavedRunCreateInput): Promise<SavedRunCheckpointV1> {
710	    if (!Number.isInteger(input.iterationLimit) || input.iterationLimit < 1 || input.iterationLimit > 8 ||
711	        !isSavedRunRepository(input.repository) || !isSavedRunConfiguration(input.configuration)) {
712	      fail('invalid_input', 'Saved run creation input is invalid.');
713	    }
714	    const state = normalizeState(input.state);
715	    if (state.repo.root !== input.repository.root || state.iteration !== 1 ||
716	        state.workerSelection !== input.configuration.workerSelection ||
717	        (state.codexNetworkAccess === true) !== input.configuration.codexNetworkAccess ||
718	        state.codexCalls !== 0 || state.claudeCalls !== 0) {
719	      fail('invalid_input', 'Saved run state does not match its repository or immutable configuration.');
720	    }
721	    if (isWithin(input.repository.root, this.directory)) {
722	      fail('invalid_input', 'Saved run storage must be outside the selected worktree.');
723	    }
724	    const storeLock = await acquireFileLock(this.directory, 'store', 'run', 'store');
725	    try {
726	      const entries = await readdir(this.runsDirectory, { withFileTypes: true });
727	      const runs = entries.filter((entry) => entry.isDirectory()).length;
728	      if (runs >= SAVED_RUN_COUNT_LIMIT) fail('limit_reached', 'Saved run store reached its record limit.');
729	      const runId = input.runId ?? randomUUID();
730	      if (!isSavedRunId(runId)) fail('invalid_input', 'Saved run ID is invalid.');
731	      const runDirectory = path.join(this.runsDirectory, runId);
732	      try { await mkdir(runDirectory, { mode: 0o700 }); } catch { fail('storage_failure', 'Unable to create saved run record.'); }
733	      if (process.platform !== 'win32') await chmod(runDirectory, 0o700);
734	      const createdAt = (input.createdAt ?? new Date()).toISOString();
735	      const identity = {
736	        schemaVersion: SAVED_RUN_SCHEMA_VERSION,
737	        runId,
738	        createdAt,
739	        iterationLimit: input.iterationLimit,
740	        repository: input.repository,
741	        configuration: input.configuration,
742	      };
743	      const event = eventToRecord({ type: 'run_created' }, 1, null,
744	        runIdentityHash(identity), sha256(JSON.stringify(state)));
745	      const eventText = `${JSON.stringify(event)}\n`;
746	      if (Buffer.byteLength(eventText, 'utf8') > SAVED_RUN_EVENT_LIMIT_BYTES) fail('limit_reached', 'Saved run event exceeds its size limit.');
747	      const checkpoint = checkpointFrom(undefined, {
748	        schemaVersion: SAVED_RUN_SCHEMA_VERSION,
749	        runId,
750	        createdAt,
751	        iterationLimit: input.iterationLimit,
752	        repository: input.repository,
753	        configuration: input.configuration,
754	        state,
755	      }, event);
756	      validateEventSequence([event], checkpoint);
757	      let eventHandle;
758	      try {
759	        eventHandle = await open(eventFilePath(this.directory, runId), 'wx', 0o600);
760	        await eventHandle.writeFile(eventText, 'utf8');
761	        await eventHandle.sync();
762	        await eventHandle.close();
763	        eventHandle = undefined;
764	        await syncDirectory(runDirectory);
765	      } catch {
766	        await eventHandle?.close().catch(() => undefined);
767	        fail('storage_failure', 'Unable to create saved run event history.');
768	      }
769	      await atomicWrite(checkpointFilePath(this.directory, runId), `${JSON.stringify(checkpoint)}\n`, SAVED_RUN_CHECKPOINT_LIMIT_BYTES);
770	      await syncDirectory(this.runsDirectory);
771	      return checkpoint;
772	    } catch (error) {
773	      if (error instanceof SavedRunStoreError) throw error;
774	      throw new SavedRunStoreError('storage_failure', 'Unable to create saved run record.');
775	    } finally {
776	      await storeLock.release();
777	    }
778	  }
