780	  async read(runId: string): Promise<{ checkpoint: SavedRunCheckpointV1; events: SavedRunEvent[] }> {
781	    if (!isSavedRunId(runId)) fail('invalid_input', 'Saved run ID is invalid.');
782	    const updateLock = await acquireFileLock(this.directory, `update-${runId}`, 'run', runId);
783	    try { return await this.readUnlocked(runId); } finally { await updateLock.release(); }
784	  }
