786	  async append(
787	    runId: string,
788	    eventData: SavedRunEventInput,
789	    nextState: SavedRunCheckpointV1['state'],
790	    repositorySnapshot?: RepositorySnapshot,
791	  ): Promise<SavedRunCheckpointV1> {
792	    if (!isSavedRunId(runId) || !isSavedRunEventData(eventData) || eventData.type === 'run_created') {
793	      fail('invalid_input', 'Saved run event input is invalid.');
794	    }
795	    const state = normalizeState(nextState);
796	    const updateLock = await acquireFileLock(this.directory, `update-${runId}`, 'run', runId);
797	    try {
798	      const { checkpoint: previous, events } = await this.readUnlocked(runId);
799	      if (repositorySnapshot !== undefined) {
800	        if (eventData.type !== 'run_stopped' || !isRepositorySnapshot(repositorySnapshot)) {
801	          fail('invalid_input', 'Repository snapshots belong only to a stopped run.');
802	        }
803	        eventData = { ...eventData, repositorySnapshotHash: snapshotHash(repositorySnapshot) };
804	      }
805	      if (['finished', 'iteration_limit', 'blocked'].includes(previous.status)) {
806	        fail('invalid_input', 'Saved run is terminal and cannot accept new events.');
807	      }
808	      if (previous.status !== 'active' && eventData.type !== 'run_resumed' && eventData.type !== 'run_blocked' &&
809	          eventData.type !== 'run_stopped' && !(previous.status === 'evaluation_failed' && eventData.type === 'iteration_limit')) {
810	        fail('invalid_input', 'Saved run must be explicitly resumed before recording more work.');
811	      }
812	      if (eventData.type === 'run_resumed') {
813	        const expectedSegment = 2 + events.filter((event) => event.type === 'run_resumed').length;
814	        if ((previous.status !== 'stopped' && previous.status !== 'evaluation_failed') || eventData.segment !== expectedSegment ||
815	            hasPendingEvaluationFailure(events) !== (eventData.evaluationRecoveryApproved === true)) {
816	          fail('invalid_input', 'Saved run continuation does not match its prior stop.');
817	        }
818	      }
819	      if (eventData.type === 'run_finished' && !hasPassedValidation(state)) {
820	        fail('invalid_input', 'Saved run cannot be marked finished without current-generation independent validation.');
821	      }
822	      if (eventData.type === 'iteration_reserved' && (eventData.iteration > previous.iterationLimit ||
823	          eventData.iteration !== Math.max(0, ...events.filter((event) => event.type === 'iteration_reserved')
824	            .map((event) => event.iteration)) + 1)) {
825	        fail('limit_reached', 'Saved run iteration limit cannot be exceeded or reset.');
826	      }
827	      if (state.task !== previous.state.task || state.repo.root !== previous.repository.root ||
828	          state.workerSelection !== previous.configuration.workerSelection ||
829	          (state.codexNetworkAccess === true) !== previous.configuration.codexNetworkAccess ||
830	          state.codexCalls < previous.state.codexCalls || state.claudeCalls < previous.state.claudeCalls) {
831	        fail('invalid_input', 'Saved run task, repository, worker, and networking settings are immutable.');
832	      }
833	      const event = eventToRecord(eventData, previous.sequence + 1, previous.ledgerHead,
834	        runIdentityHash(previous), sha256(JSON.stringify(state)));
835	      if (event.sequence > SAVED_RUN_EVENT_LIMIT) fail('limit_reached', 'Saved run event limit was reached.');
836	      const checkpoint = checkpointFrom(previous, {
837	        schemaVersion: SAVED_RUN_SCHEMA_VERSION,
838	        runId: previous.runId,
839	        createdAt: previous.createdAt,
840	        iterationLimit: previous.iterationLimit,
841	        repository: previous.repository,
842	        configuration: previous.configuration,
843	        state,
844	      }, event);
845	      validateEventSequence([...events, event], checkpoint);
846	      if (repositorySnapshot) {
847	        await atomicWrite(path.join(this.runsDirectory, runId, 'repository.json'), JSON.stringify(repositorySnapshot), SNAPSHOT_RECORD_BYTES);
848	      }
849	      await appendDurably(eventFilePath(this.directory, runId), `${JSON.stringify(event)}\n`, eventTotalLimit());
850	      await atomicWrite(checkpointFilePath(this.directory, runId), `${JSON.stringify(checkpoint)}\n`, SAVED_RUN_CHECKPOINT_LIMIT_BYTES);
851	      return checkpoint;
852	    } catch (error) {
853	      if (error instanceof SavedRunStoreError) throw error;
854	      throw new SavedRunStoreError('storage_failure', 'Unable to update saved run record.');
855	    } finally {
856	      await updateLock.release();
857	    }
858	  }
