860	  async readRepositorySnapshot(runId: string, expectedHash: string): Promise<RepositorySnapshot> {
861	    if (!isSavedRunId(runId) || !HASH_PATTERN.test(expectedHash)) fail('invalid_input', 'Repository snapshot identity is invalid.');
862	    const raw = await boundedRead(path.join(this.runsDirectory, runId, 'repository.json'), SNAPSHOT_RECORD_BYTES);
863	    let parsed: unknown;
864	    try { parsed = parseSavedRunJson(raw); } catch { fail('invalid_record', 'Saved repository snapshot is malformed.'); }
865	    if (!isRepositorySnapshot(parsed)) fail('invalid_record', 'Saved repository snapshot exceeds its contract.');
866	    if (snapshotHash(parsed) !== expectedHash) fail('integrity_failure', 'Saved repository snapshot does not match the stop ledger.');
867	    return parsed;
868	  }
