870	  private async readUnlocked(runId: string): Promise<{ checkpoint: SavedRunCheckpointV1; events: SavedRunEvent[] }> {
871	    const runDirectory = path.join(this.runsDirectory, runId);
872	    try {
873	      const directory = await lstat(runDirectory);
874	      if (!directory.isDirectory() || directory.isSymbolicLink()) fail('invalid_record', 'Saved run directory is not regular.');
875	    } catch (error) {
876	      if (hasErrorCode(error, 'ENOENT')) fail('not_found', 'Saved run record was not found.');
877	      if (error instanceof SavedRunStoreError) throw error;
878	      throw new SavedRunStoreError('storage_failure', 'Unable to read saved run record.');
879	    }
880	    let checkpoint: SavedRunCheckpointV1;
881	    let eventText: string;
882	    try {
883	      checkpoint = parseCheckpoint(await boundedRead(checkpointFilePath(this.directory, runId), SAVED_RUN_CHECKPOINT_LIMIT_BYTES));
884	      eventText = await boundedRead(eventFilePath(this.directory, runId), eventTotalLimit());
885	    } catch (error) {
886	      if (error instanceof SavedRunStoreError) throw error;
887	      throw new SavedRunStoreError('storage_failure', 'Unable to read saved run record.');
888	    }
889	    if (checkpoint.runId !== runId || !eventText.endsWith('\n')) fail('invalid_record', 'Saved run event history is incomplete.');
890	    const lines = eventText.slice(0, -1).split('\n');
891	    if (lines.length > SAVED_RUN_EVENT_LIMIT) fail('limit_reached', 'Saved run event history exceeds its limit.');
892	    const events = lines.map((line) => {
893	      if (Buffer.byteLength(line, 'utf8') > SAVED_RUN_EVENT_LIMIT_BYTES) fail('limit_reached', 'Saved run event exceeds its size limit.');
894	      let parsed: unknown;
895	      try { parsed = parseSavedRunJson(line); } catch { fail('invalid_record', 'Saved run event contains invalid JSON.'); }
896	      return parseEvent(parsed);
897	    });
898	    validateEventSequence(events, checkpoint);
899	    return { checkpoint, events };
900	  }
901	}
