361	export function defaultSavedRunDirectory(
362	  environment: NodeJS.ProcessEnv = process.env,
363	  platform: NodeJS.Platform = process.platform,
364	  homeDirectory = os.homedir(),
365	): string {
366	  if (platform === 'win32') {
367	    const localAppData = environment.LOCALAPPDATA;
368	    const root = localAppData && path.win32.isAbsolute(localAppData)
369	      ? localAppData
370	      : path.win32.join(homeDirectory, 'AppData', 'Local');
371	    return path.win32.join(root, 'dev-orchestrator', 'saved-runs');
