374	  const xdgStateHome = environment.XDG_STATE_HOME;
375	  const root = xdgStateHome && path.posix.isAbsolute(xdgStateHome)
376	    ? xdgStateHome
377	    : path.join(homeDirectory, '.local', 'state');
