386	async function boundedRead(file: string, maximumBytes: number): Promise<string> {
387	  let handle;
388	  try {
389	    const entry = await lstat(file);
390	    if (!entry.isFile() || entry.isSymbolicLink()) {
391	      fail('invalid_record', 'Saved run file is not regular.');
392	    }
393	    if (entry.nlink !== 1) fail('limit_reached', 'Saved run file is not regular or exceeds its size limit.');
394	    handle = await open(file, fsConstants.O_RDONLY | NOFOLLOW);
395	    const details = await handle.stat();
396	    if (!details.isFile() || details.nlink !== 1 || details.size > maximumBytes ||
397	        details.dev !== entry.dev || details.ino !== entry.ino) {
398	      fail('limit_reached', 'Saved run file is not regular or exceeds its size limit.');
399	    }
400	    const buffer = Buffer.alloc(maximumBytes + 1);
401	    let offset = 0;
402	    while (offset < buffer.length) {
403	      const { bytesRead } = await handle.read(buffer, offset, Math.min(64 * 1024, buffer.length - offset), offset);
404	      if (bytesRead === 0) break;
405	      offset += bytesRead;
406	      if (offset > maximumBytes) fail('limit_reached', 'Saved run file exceeds its size limit.');
407	    }
408	    return buffer.subarray(0, offset).toString('utf8');
409	  } catch (error) {
410	    if (error instanceof SavedRunStoreError) throw error;
411	    throw new SavedRunStoreError('storage_failure', 'Unable to read saved run storage.');
412	  } finally {
413	    await handle?.close().catch(() => undefined);
414	  }
