425	  const directory = path.dirname(file);
426	  const temporary = path.join(directory, `.tmp-${randomUUID()}`);
427	  let handle;
428	  try {
429	    try {
430	      const destination = await lstat(file);
431	      if (!destination.isFile() || destination.isSymbolicLink() || destination.nlink !== 1) {
432	        fail('storage_failure', 'Saved run checkpoint path is not a regular file.');
433	      }
434	    } catch (error) {
