  7	export const SAVED_RUN_LIST_LIMIT = 20;
  8	export const SAVED_RUN_TIMELINE_LIMIT = 12;
  9	
 10	type SavedRecord = Awaited<ReturnType<SavedRunStore['readForInspection']>>;
 11	
 12	/** Ledger-derived reporting only; absent and unresolved usage stays unavailable. */
 13	export function savedWorkerUsage(events: SavedRunEvent[]): WorkerUsageSummary {
 14	  const summary = emptyWorkerUsage();
 15	  for (const attempt of events) {
 16	    if (attempt.type !== 'execution_reserved' || (attempt.action !== 'CALL_CODEX' && attempt.action !== 'CALL_CLAUDE')) continue;
 17	    const outcome = events.find((event) => event.type === 'execution_outcome' && event.attemptId === attempt.attemptId);
 18	    addWorkerUsage(summary, attempt.action === 'CALL_CODEX' ? 'codex' : 'claude', outcome?.type === 'execution_outcome' ? outcome.usage : undefined);
 19	  }
 20	  return summary;
 21	}
 22	
 23	/** Reporting data only; continuation must perform its own preflight and approvals. */
 24	export type SavedRunDetail = {
 25	  kind: 'valid';
 26	  checkpoint: SavedRunCheckpointV1;
 27	  iterationsUsed: number;
 28	  iterationsRemaining: number;
 29	  checks: ReturnType<typeof validationChecks>;
 30	  repositoryAvailable: boolean;
 31	  blockers: string[];
 32	  recoveryRequired: boolean;
 33	  lastFailure?: string;
 34	  lastStop?: string;
 35	  events: SavedRunEvent[];
 36	};
 37	
 38	export type SavedRunInspectionError = {
 39	  kind: 'unavailable';
 40	  runId: string;
 41	  code: SavedRunStoreErrorCode;
 42	};
 43	
 44	export type SavedRunInspection = SavedRunDetail | SavedRunInspectionError;
 45	
 46	export function inspectionErrorText(code: SavedRunStoreErrorCode): string {
 47	  switch (code) {
 48	    case 'not_found': return 'No saved record exists for this ID.';
 49	    case 'invalid_input': return 'The run ID or saved input is invalid.';
 50	    case 'unsupported_version': return 'The saved schema version is unsupported; no migration is available.';
 51	    case 'invalid_record': return 'The saved checkpoint or event history is malformed or incomplete.';
 52	    case 'integrity_failure': return 'The checkpoint and event ledger failed integrity checks; saved state is untrusted.';
 53	    case 'limit_reached': return 'Saved storage exceeds its size/count limits or regular-file constraints (including linked or replaced files).';
 54	    case 'busy': return 'An update lock is present; a write may be active or its ownership unresolved. Retry after owner cleanup.';
 55	    case 'storage_failure': return 'Saved storage is unreadable or contains an unsafe path.';
 56	  }
 57	}
 58	
 59	async function repositoryAvailable(checkpoint: SavedRunCheckpointV1): Promise<boolean> {
 60	  try {
 61	    for (const directory of [checkpoint.repository.root, checkpoint.repository.gitCommonDirectory]) {
 62	      if (await realpath(directory) !== directory || !(await stat(directory)).isDirectory()) return false;
 63	    }
 64	    return true;
 65	  } catch {
 66	    return false;
 67	  }
 68	}
 69	
 70	const BLOCK_REASONS = {
 71	  checkpoint_invalid: 'The checkpoint was recorded as invalid.',
 72	  repository_changed: 'Repository identity or contents changed at the recorded check.',
 73	  configuration_changed: 'The recorded configuration comparison failed.',
 74	  attempt_unresolved: 'An execution attempt has no trustworthy final outcome.',
 75	  lock_stale: 'An ownership lock was recorded as unresolved.',
 76	  storage_failure: 'A required saved-state write failed.',
 77	} as const;
 78	
 79	function summarizeRecord(record: SavedRecord, available: boolean): SavedRunDetail {
 80	  const { checkpoint, events, ownership } = record;
 81	  const newestFirst = [...events].reverse();
 82	  const iterationsUsed = events.filter((event) => event.type === 'iteration_reserved').length;
 83	  const iterationsRemaining = checkpoint.iterationLimit - iterationsUsed;
 84	  const blockers: string[] = [];
 85	  const stop = newestFirst.find((event) => event.type === 'run_stopped');
 86	  const lastEvent = events.at(-1);
 87	  const completed = new Set(events.filter((event) => event.type === 'execution_outcome').map((event) => event.attemptId));
 88	  const unresolved = events.filter((event) => event.type === 'execution_reserved' && !completed.has(event.attemptId));
 89	  const uncertain = events.filter((event) => event.type === 'execution_outcome' && event.outcome === 'uncertain');
 90	  if (checkpoint.status === 'finished') blockers.push('Task completion was approved; this run is inspection only.');
 91	  if (checkpoint.status === 'iteration_limit' || iterationsRemaining === 0) {
 92	    blockers.push('The original iteration budget is exhausted; continuation cannot extend it.');
 93	  }
 94	  if (checkpoint.status === 'active' || checkpoint.status === 'evaluation_failed') {
 95	    blockers.push('No durable clean stop is recorded; active or abruptly exited runs cannot continue.');
 96	  }
 97	  if (lastEvent?.type === 'run_blocked') blockers.push(BLOCK_REASONS[lastEvent.reason]);
 98	  if (stop?.type === 'run_stopped' && !stop.resumable && checkpoint.status === 'blocked') {
 99	    blockers.push(`The recorded ${stop.reason} stop was not marked resumable.`);
100	  }
101	  if (checkpoint.status === 'stopped' && stop?.type === 'run_stopped' && !stop.repositorySnapshotHash) {
102	    blockers.push('This stop predates content fingerprints and remains inspection only; start a new saved run.');
103	  }
104	  if (unresolved.length > 0) {
105	    blockers.push(`${unresolved.length} reserved execution attempt(s) have no outcome; their allowances stay charged.`);
106	  }
107	  if (uncertain.length > 0) blockers.push('An execution outcome is uncertain; do not replay the reserved action.');
108	  if (ownership.run) blockers.push('A run ownership lock is present; the owner may be active or unresolved.');
109	  if (ownership.worktree) blockers.push('A worktree ownership lock is present; the owner may be active or unresolved.');
110	  if (!available) blockers.push('The saved repository or Git directory is unavailable at its canonical path.');
111	  const evaluationFailure = newestFirst.find((event) => event.type === 'evaluation_failed');
112	  const recoveryRequired = evaluationFailure !== undefined &&
113	    !events.some((event) => event.type === 'evaluation_completed' && event.sequence > evaluationFailure.sequence);
114	  const failedEvent = newestFirst.find((event) => event.type === 'evaluation_failed' ||
115	    (event.type === 'execution_outcome' && event.outcome !== 'succeeded') || event.type === 'run_blocked');
116	  let lastFailure: string | undefined;
117	  if (failedEvent?.type === 'evaluation_failed') {
118	    lastFailure = `Iteration ${failedEvent.iteration}: ${failedEvent.code} at ${failedEvent.stage}/${failedEvent.category}.`;
119	  } else if (failedEvent?.type === 'execution_outcome') {
120	    const attempt = events.find((event) => event.type === 'execution_reserved' && event.attemptId === failedEvent.attemptId);
121	    const failure = checkpoint.state.evidence?.failures.slice().reverse().find((item) =>
122	      attempt?.type === 'execution_reserved' && item.iteration === attempt.iteration && item.action === attempt.action);
123	    lastFailure = `${attempt?.type === 'execution_reserved' ? `Iteration ${attempt.iteration}: ${attempt.action}` : 'Execution'} ${failedEvent.outcome}.${failure ? ` ${failure.summary}` : ''}`;
124	  } else if (failedEvent?.type === 'run_blocked') {
125	    lastFailure = BLOCK_REASONS[failedEvent.reason];
126	  }
127	  if (checkpoint.state.evidence?.repoRefreshRequired) {
128	    blockers.push('The saved state requires repository refresh before validation can confirm completion.');
129	  }
130	  if (hasOmittedValidationRequirements(checkpoint.state)) {
131	    blockers.push('Validation requirements were omitted; completion remains blocked.');
132	  }
133	  return {
134	    kind: 'valid', checkpoint, iterationsUsed, iterationsRemaining,
135	    checks: validationChecks(checkpoint.state), repositoryAvailable: available,
136	    blockers, recoveryRequired,
137	    ...(lastFailure === undefined ? {} : { lastFailure }),
138	    ...(stop?.type === 'run_stopped' ? { lastStop: `${stop.reason}; ${stop.resumable ? 'clean continuation point recorded' : 'not resumable'}` } : {}),
139	    events,
140	  };
141	}
142	
143	export async function inspectSavedRun(store: SavedRunStore | undefined, runId: string): Promise<SavedRunInspection> {
144	  if (!store) return { kind: 'unavailable', runId, code: 'not_found' };
145	  try {
146	    const record = await store.readForInspection(runId);
147	    const detail = summarizeRecord(record, await repositoryAvailable(record.checkpoint));
148	    const stop = record.events.at(-1);
149	    if (stop?.type === 'run_stopped' && stop.repositorySnapshotHash) {
150	      try { await store.readRepositorySnapshot(runId, stop.repositorySnapshotHash); } catch (error) {
151	        detail.blockers.push(`Repository comparison evidence is unavailable: ${inspectionErrorText(error instanceof SavedRunStoreError ? error.code : 'storage_failure')}`);
152	      }
153	    }
154	    return detail;
155	  } catch (error) {
156	    return { kind: 'unavailable', runId, code: error instanceof SavedRunStoreError ? error.code : 'storage_failure' };
157	  }
158	}
