160	export type SavedRunListing = {
161	  runs: SavedRunInspection[];
162	  total: number;
163	  ignoredEntries: number;
164	  hiddenRuns: number;
165	};
166	
167	export async function listSavedRuns(store: SavedRunStore | undefined): Promise<SavedRunListing> {
168	  if (!store) return { runs: [], total: 0, ignoredEntries: 0, hiddenRuns: 0 };
169	  const { runIds, ignoredEntries } = await store.listIdsForInspection();
170	  const runs: SavedRunInspection[] = [];
171	  // Each record is bounded by the store's byte/event limits. Read sequentially
172	  // so listing cannot allocate the entire store's raw data at once.
173	  for (const runId of runIds) runs.push(await inspectSavedRun(store, runId));
174	  runs.sort((left, right) => {
175	    // Unreadable records are always visible before recent valid records. Do not
176	    // trust a malformed checkpoint's timestamp to rank or hide its warning.
177	    if (left.kind !== right.kind) return left.kind === 'unavailable' ? -1 : 1;
178	    if (left.kind === 'valid' && right.kind === 'valid') {
179	      return right.checkpoint.updatedAt.localeCompare(left.checkpoint.updatedAt) ||
180	        left.checkpoint.runId.localeCompare(right.checkpoint.runId);
181	    }
182	    return left.kind === 'unavailable' && right.kind === 'unavailable' ? left.runId.localeCompare(right.runId) : 0;
183	  });
184	  return {
185	    runs: runs.slice(0, SAVED_RUN_LIST_LIMIT), total: runs.length, ignoredEntries,
186	    hiddenRuns: Math.max(0, runs.length - SAVED_RUN_LIST_LIMIT),
187	  };
188	}
189	
190	export function describeSavedEvent(event: SavedRunEvent): string {
191	  switch (event.type) {
192	    case 'iteration_reserved': return `iteration_reserved ${event.iteration}`;
193	    case 'evaluation_completed': return `evaluation_completed ${event.iteration}`;
194	    case 'evaluation_failed': return `evaluation_failed ${event.iteration}: ${event.code} at ${event.stage}/${event.category}`;
195	    case 'action_approved': return `action_approved ${event.iteration}: ${event.action} (${event.decision})`;
196	    case 'execution_reserved': return `execution_reserved ${event.iteration}: ${event.action}`;
197	    case 'execution_outcome': return `execution_outcome: ${event.outcome}`;
198	    case 'clarification_recorded': return `clarification_recorded ${event.iteration}`;
199	    case 'run_stopped': return `run_stopped: ${event.reason}; resumable=${event.resumable}`;
200	    case 'run_blocked': return `run_blocked: ${event.reason}`;
201	    case 'run_resumed': return `run_resumed: segment ${event.segment}`;
202	    default: return event.type;
203	  }
204	}

