 38	async function git(root: string, args: string[], required = false): Promise<string> {
 39	  return new Promise((resolve, reject) => {
 40	    const child = spawn('git', ['-c', 'core.fsmonitor=false', ...args], {
 41	      cwd: root,
 42	      stdio: ['ignore', 'pipe', 'ignore'],
 43	      env: {
 44	        ...process.env,
 45	        GIT_OPTIONAL_LOCKS: '0',
 46	        GIT_TERMINAL_PROMPT: '0',
 47	      },
 48	    });
 49	    let output = '';
 50	    let outputBytes = 0;
 51	    let interrupted = false;
 52	    let settled = false;
 53	    const timeout = setTimeout(() => {
 54	      interrupted = true;
 55	      child.kill();
 56	    }, GIT_TIMEOUT_MS);
 57	    timeout.unref();
 58	
 59	    const finish = (value: string, success = false): void => {
 60	      if (settled) return;
 61	      settled = true;
 62	      clearTimeout(timeout);
 63	      if (required && !success) reject(new Error('Unable to collect bounded Git file metadata.'));
 64	      else resolve(value);
 65	    };
 66	
 67	    child.stdout.on('data', (chunk: Buffer) => {
 68	      if (interrupted) return;
 69	
 70	      const availableBytes = MAX_GIT_OUTPUT_BYTES - outputBytes;
 71	      if (availableBytes <= 0 || chunk.length > availableBytes) {
 72	        interrupted = true;
 73	        child.kill();
 74	        return;
 75	      }
 76	
 77	      output += chunk.toString('utf8');
 78	      outputBytes += chunk.length;
 79	    });
 80	    child.on('error', () => finish(''));
 81	    child.on('close', (code) => // Leading spaces are fixed-width Git status columns, not padding.
 82	      finish(code === 0 && !interrupted ? output.replace(/\r?\n$/u, '') : '', code === 0 && !interrupted));
 83	  });
 84	}
