188	export async function inspectGitIdentity(root: string): Promise<{
189	  root: string;
190	  gitCommonDirectory: string;
191	  head: string;
192	}> {
193	  let canonicalRoot: string;
194	  try {
195	    canonicalRoot = await realpath(root);
196	  } catch {
197	    throw new Error('Saved runs require an available Git worktree.');
198	  }
199	  const [gitRoot, gitCommonDirectory, head] = await Promise.all([
200	    git(canonicalRoot, ['rev-parse', '--show-toplevel']),
201	    git(canonicalRoot, ['rev-parse', '--git-common-dir']),
202	    git(canonicalRoot, ['rev-parse', '--verify', 'HEAD^{commit}']),
203	  ]);
204	  if (!gitRoot || !gitCommonDirectory || !/^[a-f0-9]{40}(?:[a-f0-9]{24})?$/iu.test(head)) {
205	    throw new Error('Saved runs require a Git worktree with a committed HEAD.');
206	  }
207	  const reportedGitCommonDirectory = path.resolve(canonicalRoot, gitCommonDirectory);
208	  let canonicalGitRoot: string;
209	  let canonicalGitCommonDirectory: string;
210	  try {
211	    [canonicalGitRoot, canonicalGitCommonDirectory] = await Promise.all([
212	      realpath(gitRoot), realpath(reportedGitCommonDirectory),
213	    ]);
214	  } catch {
215	    throw new Error('Saved run Git identity is unavailable.');
216	  }
217	  const pathIdentity = (value: string): string => process.platform === 'win32' ? value.toLowerCase() : value;
218	  if (pathIdentity(canonicalGitRoot) !== pathIdentity(canonicalRoot)) {
219	    throw new Error('Saved run path does not resolve to the selected Git worktree.');
220	  }
221	  return {
222	    root: canonicalRoot,
223	    gitCommonDirectory: canonicalGitCommonDirectory,
224	    head: head.toLowerCase(),
225	  };
226	}
