 12	/** Ledger-derived reporting only; absent and unresolved usage stays unavailable. */
 13	export function savedWorkerUsage(events: SavedRunEvent[]): WorkerUsageSummary {
 14	  const summary = emptyWorkerUsage();
 15	  for (const attempt of events) {
