 46	export function inspectionErrorText(code: SavedRunStoreErrorCode): string {
 47	  switch (code) {
 48	    case 'not_found': return 'No saved record exists for this ID.';
 49	    case 'invalid_input': return 'The run ID or saved input is invalid.';
 50	    case 'unsupported_version': return 'The saved schema version is unsupported; no migration is available.';
 51	    case 'invalid_record': return 'The saved checkpoint or event history is malformed or incomplete.';
 52	    case 'integrity_failure': return 'The checkpoint and event ledger failed integrity checks; saved state is untrusted.';
 53	    case 'limit_reached': return 'Saved storage exceeds its size/count limits or regular-file constraints (including linked or replaced files).';
 54	    case 'busy': return 'An update lock is present; a write may be active or its ownership unresolved. Retry after owner cleanup.';
 55	    case 'storage_failure': return 'Saved storage is unreadable or contains an unsafe path.';
