 70	const BLOCK_REASONS = {
 71	  checkpoint_invalid: 'The checkpoint was recorded as invalid.',
 72	  repository_changed: 'Repository identity or contents changed at the recorded check.',
 73	  configuration_changed: 'The recorded configuration comparison failed.',
 74	  attempt_unresolved: 'An execution attempt has no trustworthy final outcome.',
 75	  lock_stale: 'An ownership lock was recorded as unresolved.',
 76	  storage_failure: 'A required saved-state write failed.',
 77	} as const;
