143	export async function inspectSavedRun(store: SavedRunStore | undefined, runId: string): Promise<SavedRunInspection> {
144	  if (!store) return { kind: 'unavailable', runId, code: 'not_found' };
145	  try {
146	    const record = await store.readForInspection(runId);
147	    const detail = summarizeRecord(record, await repositoryAvailable(record.checkpoint));
148	    const stop = record.events.at(-1);
149	    if (stop?.type === 'run_stopped' && stop.repositorySnapshotHash) {
150	      try { await store.readRepositorySnapshot(runId, stop.repositorySnapshotHash); } catch (error) {
151	        detail.blockers.push(`Repository comparison evidence is unavailable: ${inspectionErrorText(error instanceof SavedRunStoreError ? error.code : 'storage_failure')}`);
152	      }
153	    }
154	    return detail;
155	  } catch (error) {
156	    return { kind: 'unavailable', runId, code: error instanceof SavedRunStoreError ? error.code : 'storage_failure' };
157	  }
158	}
