190	export function describeSavedEvent(event: SavedRunEvent): string {
191	  switch (event.type) {
192	    case 'iteration_reserved': return `iteration_reserved ${event.iteration}`;
193	    case 'evaluation_completed': return `evaluation_completed ${event.iteration}`;
194	    case 'evaluation_failed': return `evaluation_failed ${event.iteration}: ${event.code} at ${event.stage}/${event.category}`;
195	    case 'action_approved': return `action_approved ${event.iteration}: ${event.action} (${event.decision})`;
196	    case 'execution_reserved': return `execution_reserved ${event.iteration}: ${event.action}`;
197	    case 'execution_outcome': return `execution_outcome: ${event.outcome}`;
198	    case 'clarification_recorded': return `clarification_recorded ${event.iteration}`;
199	    case 'run_stopped': return `run_stopped: ${event.reason}; resumable=${event.resumable}`;
200	    case 'run_blocked': return `run_blocked: ${event.reason}`;
201	    case 'run_resumed': return `run_resumed: segment ${event.segment}`;
202	    default: return event.type;
203	  }
204	}

