  3	export const VALIDATION_NAMES = ['verify', 'check', 'test', 'typecheck', 'lint', 'build'] as const;
  4	
  5	export function isValidationScript(script: string): boolean {
  6	  return /^[a-zA-Z0-9][a-zA-Z0-9:_-]{0,199}$/u.test(script) &&
  7	    VALIDATION_NAMES.some((name) => script === name || script.startsWith(`${name}:`));
  8	}
  9	
 10	export function validationRequirementsFromText(text: string): { scripts: string[]; truncated: boolean } {
 11	  const scripts: string[] = [];
 12	  for (const match of text.matchAll(/\b(?:npm|pnpm|yarn|bun)\s+(?:run\s+)?([a-zA-Z0-9][a-zA-Z0-9:_-]{0,199})\b/gu)) {
 13	    if (match[1] && isValidationScript(match[1]) && !scripts.includes(match[1])) scripts.push(match[1]);
 14	    if (scripts.length > 8) return { scripts: scripts.slice(0, 8), truncated: true };
 15	  }
 16	  return { scripts, truncated: false };
 17	}
 18	
 19	function clarificationValidation(state: AgentState): { scripts: string[]; truncated: boolean } {
 20	  return validationRequirementsFromText((state.evidence?.clarifications ?? []).map((item) => item.text).join('\n'));
 21	}
 22	
 23	export function hasOmittedValidationRequirements(state: AgentState): boolean {
 24	  return state.evidence?.issue?.validationRequirementsTruncated === true || clarificationValidation(state).truncated;
 25	}
