  2	import { interruptible, RunInterruptedError, throwIfInterrupted, type ExecutionOptions } from '../cancellation.js';
  3	import { resolveEvaluationConfiguration, validateCloudflareAccountId, validateEvaluationModel, type EvaluationConfiguration } from '../config.js';
  4	import { redactSensitiveText, withRedactionSecrets } from '../logging/trace.js';
  5	import type { AgentState, EvaluationResult } from '../types.js';
  6	import { boundAgentStateForEvaluation } from './contract.js';
  7	import {
  8	  evaluationRetryDelay, isTransientEvaluationError, EVALUATION_MAX_RETRIES,
