 10	} from './errors.js';
 11	import { evaluateNative } from './native.js';
 12	import { evaluateVercel } from './vercel.js';
 13	import { evaluateCloudflare } from './cloudflare.js';
 14	
 15	export { boundAgentStateForEvaluation } from './contract.js';
 16	export { EvaluationError, EVALUATION_MAX_RETRIES, EVALUATION_TIMEOUT_MS, normalizeEvaluationError } from './errors.js';
 17	export type { EvaluationErrorCode } from './errors.js';
 18	export { JevEvaluationError, JEV_EVALUATION_MAX_RETRIES, JEV_EVALUATION_TIMEOUT_MS, normalizeJevEvaluationError } from './errors.js';
 19	export type { JevEvaluationErrorCode } from './errors.js';
 20	
 21	/** Loop-owned routing context; never restored from task text or an approved candidate. */
 22	export type EvaluationOptions = ExecutionOptions & { iterationLimit?: number };
 23	
 24	export type Evaluator = (state: AgentState, options?: EvaluationOptions) => Promise<EvaluationResult>;
 25	
 26	/** Bind transport credentials and model once, outside serializable run state. */
 27	export function createEvaluator(
 28	  configuration: EvaluationConfiguration = resolveEvaluationConfiguration(),
 29	  modelOverride?: EvaluationModel,
 30	): Evaluator {
 31	  const selected = Object.freeze({ ...configuration, model: typeof modelOverride === 'string' ? modelOverride : configuration.model });
 32	  validateEvaluationModel(selected.provider, selected.model);
 33	  if (selected.provider === 'cloudflare') validateCloudflareAccountId(selected.accountId);
 34	  if (modelOverride !== undefined && typeof modelOverride !== 'string' && selected.provider !== 'vercel') {
 35	    throw new Error('An SDK evaluation model override requires ROUTER_PROVIDER=vercel.');
 36	  }
 37	  return (state, options = {}) => withRedactionSecrets([selected.apiKey], () =>
 38	    evaluateConfiguredState(state, selected, options, typeof modelOverride === 'string' ? undefined : modelOverride));
 39	}
