 41	function waitForRetry(milliseconds: number, signal: AbortSignal): Promise<void> {
 42	  throwIfInterrupted(signal);
 43	  return new Promise((resolve, reject) => {
 44	    const finish = (): void => {
 45	      signal.removeEventListener('abort', abort);
 46	      resolve();
 47	    };
 48	    const timer = setTimeout(finish, milliseconds);
 49	    const abort = (): void => {
 50	      clearTimeout(timer);
 51	      signal.removeEventListener('abort', abort);
 52	      reject(new RunInterruptedError());
 53	    };
 54	    signal.addEventListener('abort', abort, { once: true });
 55	  });
 56	}
 57	
 58	export async function evaluateAgentState(
 59	  state: AgentState,
 60	  model?: EvaluationModel,
 61	  options: EvaluationOptions = {},
 62	): Promise<EvaluationResult> {
 63	  throwIfInterrupted(options.signal);
 64	  return createEvaluator(resolveEvaluationConfiguration(), model)(state, options);
 65	}
 66	
 67	async function evaluateConfiguredState(
 68	  state: AgentState,
 69	  configuration: EvaluationConfiguration,
 70	  options: EvaluationOptions,
 71	  modelOverride?: EvaluationModel,
 72	): Promise<EvaluationResult> {
 73	  throwIfInterrupted(options.signal);
 74	  const startedAt = performance.now();
 75	  const snapshot = boundAgentStateForEvaluation(state, options.iterationLimit);
 76	  const deadline = new AbortController();
 77	  const timeout = setTimeout(() => deadline.abort(), EVALUATION_TIMEOUT_MS);
 78	  const signal = options.signal ? AbortSignal.any([options.signal, deadline.signal]) : deadline.signal;
 79	  try {
 80	    for (let attempt = 0; ; attempt += 1) {
 81	      try {
 82	        const result = await interruptible(() => {
 83	          if (configuration.provider === 'cloudflare') return evaluateCloudflare(snapshot, configuration, signal);
 84	          return configuration.provider === 'vercel'
 85	            ? evaluateVercel(snapshot, configuration, signal, modelOverride)
 86	            : evaluateNative(snapshot, { ...configuration, provider: configuration.provider }, signal);
 87	        }, signal);
 88	        throwIfInterrupted(signal);
 89	        return {
