 41	function waitForRetry(milliseconds: number, signal: AbortSignal): Promise<void> {
 42	  throwIfInterrupted(signal);
 43	  return new Promise((resolve, reject) => {
 44	    const finish = (): void => {
 45	      signal.removeEventListener('abort', abort);
 46	      resolve();
 47	    };
 48	    const timer = setTimeout(finish, milliseconds);
 49	    const abort = (): void => {
 50	      clearTimeout(timer);
 51	      signal.removeEventListener('abort', abort);
 52	      reject(new RunInterruptedError());
 53	    };
 54	    signal.addEventListener('abort', abort, { once: true });
 55	  });
 56	}
